// Buffer: Henderson-Hasselbalch. pH = pKa + log([A-]/[HA]).
// Start with equal moles HA and A- (1 L). Add strong base 'b' mol (converts HA->A-)
// or strong acid (b<0, converts A-->HA). Compare to adding same to pure water.
const pKa = 4.74;          // acetic / acetate buffer
const n0 = 0.50;           // initial moles HA = moles A- (in 1 L)
function pHbuf(b){
  // b = mol strong base added (negative = strong acid)
  const HA = n0 - b;
  const A  = n0 + b;
  if (HA <= 1e-6) return 7 + 6;          // past capacity (base side) -> jumps up
  if (A  <= 1e-6) return 1;              // past capacity (acid side) -> jumps down
  return pKa + Math.log10(A / HA);
}
function pHwater(b){
  // adding b mol strong base (or acid) to 1 L pure water
  if (b > 0){ const OH = b; const pOH = -Math.log10(Math.max(OH,1e-14)); return 14 - pOH; }
  if (b < 0){ const Hc = -b; return -Math.log10(Math.max(Hc,1e-14)); }
  return 7;
}
